// Formatear mensaje de seguimiento con pregunta de confirmación
const order = $input.first().json;
const nombre = order.guest_name || 'amigo/a';
const edad = order.cart_age_days || 1;
const total = Number(order.total_amount) || 0;
const prePedido = order.order_data?.items || [];
const horasLaborables = Math.floor(order.horas_laborables || 0);

// Determinar mensaje según seguimiento
let mensaje_seguimiento = '';

if (horasLaborables >= 3 && horasLaborables < 6) {
  mensaje_seguimiento = 'Ya han pasado 3 horas laborables desde que creaste tu carrito.\n\n¿Te gustaría confirmar el pedido?';
} else if (horasLaborables >= 6 && horasLaborables < 9) {
  mensaje_seguimiento = 'Tu pedido lleva más de 6 horas laborables sin confirmar.\n\n¿Deseas confirmar este pedido ahora?';
} else if (horasLaborables >= 9 && horasLaborables < 12) {
  mensaje_seguimiento = 'Tu pedido lleva más de 9 horas laborables.\n\n¿Deseas confirmar este pedido?';
} else {
  mensaje_seguimiento = 'Tu pedido lleva más de 12 horas laborables.\n\n¿Deseas confirmar este pedido?';
}

// Calcular día de entrega
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Dom, 1=Lun, etc.
let proximaEntrega = 'Martes';
if (dayOfWeek >= 2 && dayOfWeek <= 4) {
  proximaEntrega = 'Viernes';
} else {
  proximaEntrega = 'Martes';
}

// Formatear lista de productos
let productosTexto = '';
if (Array.isArray(prePedido) && prePedido.length > 0) {
  productosTexto = prePedido.map((item, i) => {
    const nombre = item.productName || item.producto_nombre || 'Producto';
    const precio = Number(item.price) || Number(item.precio) || 0;
    const cantidad = item.quantity || item.cantidad || 1;
    return `• ${nombre} x${cantidad} - $${precio.toLocaleString('es-CO')}`;
  }).join('\n');
} else {
  productosTexto = '• Tus productos favoritos están listos';
}

const mensaje = `📝 SEGUIMIENTO DE PEDIDO\n\nHola ${nombre},\n\n${mensaje_seguimiento}\n\n${productosTexto}\n\n💰 *Total: $${total.toLocaleString('es-CO')}*\n\n🚚 Te podemos entregar el *${proximaEntrega}*\n\n¿Deseas:\n1️⃣ Confirmar el pedido\n2️⃣ Dejar el carrito así\n3️⃣ Revisar el carrito`;

return {
  json: {
    orderId: order.id,
    nombre: nombre,
    telefono: order.guest_phone,
    email: order.guest_email,
    mensaje: mensaje,
    totalCarrito: total,
    cartAge: edad,
    horasLaborables: horasLaborables,
    productos: prePedido,
    proximaEntrega: proximaEntrega,
    opciones: 3
  }
};

