UPDATE guest_orders
SET
  abandoned_whatsapp_sent = true,
  abandoned_reminder_sent = jsonb_set(abandoned_reminder_sent,
    to_jsonb('whatsapp_3horas'),
    to_jsonb((abandoned_reminder_sent->>'whatsapp_3horas')::jsonb || {"sent_at": "{{ now() }}"})
  )
WHERE id = '{{ $('📝 Formatear Mensaje Seguimiento').first().json.orderId }}';

RETURNING id, abandoned_whatsapp_sent, abandoned_reminder_sent;
